STEPS_PER_MM = 8
TELEMETRY_STEPS_PER_MM = 4


def to_millimetres(steps: int) -> int:
    return steps // STEPS_PER_MM


def to_steps(millimetres: int) -> int:
    return millimetres * TELEMETRY_STEPS_PER_MM

